const base = { 2: "two", label: "base", 1: "one" };
const item = Object.create(base);
item.label = "item";
item.note = "new";
item[10] = "ten";

const keys = [];
for (const key in item) {
  keys.push(key);
}

console.log(keys.join(","));
console.log(Object.keys(item).join(","));
console.log(item[1], Object.hasOwn(item, 1));
